    &= \quad{k \choose 2} \frac{1}{|\mathcal{H}|} \mathbb{E}_{l_1,l_2 \sim \mathcal{U}(\mathcal{H})}\left( | C^*(l_1) \cap C^*(l_2) | \right)\\
    &= \quad{k \choose 2} \frac{1}{|\mathcal{H}|} \mathbb{E}_{l_1 \sim \mathcal{U}(\mathcal{H})}\left(\mathbb{E}_{l_2 \sim \mathcal{U}(\mathcal{H})}( | C^*(l_1) \cap C^*(l_2) | )\right)\\
    &= \quad{k \choose 2} \frac{1}{|\mathcal{H}|} \mathbb{E}_{l_1 \sim \mathcal{U}(\mathcal{H})}\left(\sum_{r \in C^*(l_1)}\Pr_{l_2 \sim \mathcal{U}(\mathcal{H})}\left(r \in C^*(l_2)\right) \right)\\
    &\leq \quad{k \choose 2} \frac{1}{|\mathcal{H}|} \mathbb{E}_{l_1 \sim \mathcal{U}(\mathcal{H})}\left(\sum_{r \in C^*(l_1)}\Pr_{l_2 \sim \mathcal{U}(\mathcal{H})}\left(l_2 \in C(r)\right) \right)\\
    &= \quad{k \choose 2} \frac{1}{|\mathcal{H}|} \mathbb{E}_{l_1 \sim \mathcal{U}(\mathcal{H})}\left(\sum_{r \in C^*(l_1)} \|C(r)\| \right)\\
