Let $Z^*$, $\hat Z$ and $D$ be as defined above.
Then $\Pr\left(Z^* < \mathbb{E}(\hat Z)/4\right) \leq (c_4)^n$  where $c_4$ is a constant $\in (0, 1)$ and $n$ large enough.
\label{lem:largeZ}

We can bound the probability that $Z^*$ deviates too much from $\mathbb{E}(\hat Z)/4$ as follows.
In the step annotated with $*$, we use the Markov inequality ($\Pr(D \geq a)\leq \mathbb{E}(D)/a$).
\begin{align*}
  \Pr&\left(Z^* < \mathbb{E}(\hat Z)/4\right)
    \hspace{3mm}\refRelObs{cor:upperLower}{\leq} \Pr\left(\hat Z - D < \mathbb{E}(\hat Z)/4\right)\\
    &\leq \quad \Pr\left(\hat Z < \mathbb{E}(\hat Z)/2 \vee D \geq \mathbb{E}(\hat Z)/4\right)\\
    &\leq \quad \Pr\left(\hat Z < \mathbb{E}(\hat Z)/2\right) + \Pr\left(D \geq \mathbb{E}(\hat Z)/4\right)\\
    &\refRelLem{lem:sConcentration}{\leq} (c_3)^n +\Pr\left(D \geq \mathbb{E}(\hat Z)/4\right)
    \overset{*}{\leq} (c_3)^n + \frac{\mathbb{E}(D)}{\mathbb{E}(\hat Z)/4}\\
    &\refRelLem{lem:smallD}{\leq} (c_3)^n + (c_2)^{n/2}/4
    \leq (c_4)^n \textrm{ for some $c_4 \in (0, 1)$ and $n$ large enough.}
  \tag*{\qedhere}
\end{align*}

\begin{align*}
    \Pr&\left(Z^* < \mathbb{E}(\hat Z)/4\right)
      \hspace{3mm}\refRelObs{cor:upperLower}{\leq} \Pr\left(\hat Z - D < \mathbb{E}(\hat Z)/4\right)\\
      &\leq \quad \Pr\left(\hat Z < \mathbb{E}(\hat Z)/2 \vee D \geq \mathbb{E}(\hat Z)/4\right)\\
      &\leq \quad \Pr\left(\hat Z < \mathbb{E}(\hat Z)/2\right) + \Pr\left(D \geq \mathbb{E}(\hat Z)/4\right)\\
